GET /abc123 HTTP/1.1
Host: short.ly

HTTP/1.1 302 Found
Location: https://example.com/a/very/long/article
Cache-Control: no-store

// handler mental model
async function redirect(shortCode) {
  const row = await db.urls.findByShortCode(shortCode);
  if (!row) return Response.json({ error: 'not found' }, { status: 404 });
  if (row.expiresAt && row.expiresAt < Date.now()) return new Response(null, { status: 410 });
  return new Response(null, {
    status: 302,
    headers: { Location: row.longUrl, 'Cache-Control': 'no-store' }
  });
}
